import { taxCents } from "./tax";

export interface Invoice {
  id: string;
  subtotalCents: number;
  taxRatePercent: number;
}

export function totalCents(invoice: Invoice): number {
  return invoice.subtotalCents + taxCents(invoice.subtotalCents, invoice.taxRatePercent);
}
export function pageBounds(page: number, pageSize: number, total: number): { start: number; end: number } {
  const start = (page - 1) * pageSize;
  const end = Math.min(start + pageSize - 1, total);
  return { start, end };
}

import type { Invoice } from "../billing/invoice";

export function InvoiceList({ invoices }: { invoices: Invoice[] }) {
  return <ul>{invoices.map((invoice) => <li key={invoice.id}>{invoice.id}</li>)}</ul>;
}
